CREATE     PROCEDURE [synapse_fo].[usp_Insert_PROJTABLE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:57
	Description: Insert stored procedure for PROJTABLE from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[PROJTABLE]
	(
		[ALERTTIMEFRAMEWEEKS],
		[ALTERNATEBUDGETPROJECT],
		[ASSETID],
		[BANKDOCUMENTTYPE],
		[CERTIFIEDPAYROLL],
		[CHECKBUDGET],
		[COMPLETESCHEDULED],
		[CONTRACTAMENDMENT_SA],
		[CONTRACTDATE_SA],
		[CONTRACTPERIOD_SA],
		[CONTRACTVALUE_SA],
		[CREATED],
		[CUSTACCOUNT],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DEFAULTDIMENSION],
		[DEFAULTFUNDINGSOURCE],
		[DELIVERYLOCATION],
		[DESCRIPTION],
		[DLVNAME],
		[EMAIL],
		[ENDDATE],
		[EXTENSIONDATE],
		--[FileName],
		[FORMAT],
		[HEADER],
		[JOBID],
		[JOBPAYTYPE],
		[LastProcessedChange_DateTime],
		--[LSN],
		[MINTIMEINCREMENT],
		[MODIFIEDDATETIME],
		[NAME],
		[OCIP],
		[OCIPGL],
		[PARENTID],
		[PARTITION],
		[PROJBUDGETARYCONTROLON],
		[PROJBUDGETINTERVAL],
		[PROJBUDGETMANAGEMENT],
		[PROJBUDGETOVERRUNOPTION],
		[PROJCARRYFORWARDNEGATIVEBUDGET],
		[PROJCARRYFORWARDREMAININGBUDGET],
		[PROJDATASOURCE],
		[PROJECTEDENDDATE],
		[PROJECTEDSTARTDATE],
		[PROJGROUPID],
		[PROJID],
		[PROJINVOICEPROJID],
		[PROJLEDGERPOSTING],
		[PROJLINEPROPERTYSEARCH],
		[PROJPRICEGROUP],
		[PSADOINVOICECOST],
		[PSAFORECASTMODELID],
		[PSAFORECASTMODELIDEXTERNAL],
		[PSAINVOICEMETHOD],
		[PSAPROJSTATUS],
		[PSARESSCHEDSTATUS],
		[PSASCHEDCALENDARID],
		[PSASCHEDDURATION],
		[PSASCHEDEFFORT],
		[PSASCHEDENDDATE],
		[PSASCHEDFROMTIME],
		[PSASCHEDIGNORECALENDAR],
		[PSASCHEDMILESTONE],
		[PSASCHEDSCHEDULED],
		[PSASCHEDSTARTDATE],
		[PSASCHEDTOTIME],
		[PSASCHEDUSEDURATION],
		[RECID],
		[RECVERSION],
		[REQUIREACTIVITYEXPENSEFORECAST],
		[REQUIREACTIVITYEXPENSETRX],
		[REQUIREACTIVITYHOURFORECAST],
		[REQUIREACTIVITYHOURTRX],
		[REQUIREACTIVITYITEMFORECAST],
		[REQUIREACTIVITYITEMTRX],
		[SORTINGID],
		[SORTINGID2_],
		[SORTINGID3_],
		[STARTDATE],
		[STATUS],
		[SUBJECT_SA],
		--[SysRowId],
		[TAXGROUPID],
		[TEMPLATE],
		[TEMPLATEAPPLIED],
		[TIMEPOSTDETAILSUMMARY],
		[TYPE],
		[USEALTERNATEPROJECT],
		[USEBUDGETING],
		[VALIDATEPROJCATEGORY],
		[WIPPROJECT],
		[WORKERPSAARCHITECT],
		[WORKERRESPONSIBLE],
		[WORKERRESPONSIBLEFINANCIAL],
		[WORKERRESPONSIBLESALES]
	)
	SELECT 
		stg.[ALERTTIMEFRAMEWEEKS],
		stg.[ALTERNATEBUDGETPROJECT],
		stg.[ASSETID],
		stg.[BANKDOCUMENTTYPE],
		stg.[CERTIFIEDPAYROLL],
		stg.[CHECKBUDGET],
		stg.[COMPLETESCHEDULED],
		stg.[CONTRACTAMENDMENT_SA],
		stg.[CONTRACTDATE_SA],
		stg.[CONTRACTPERIOD_SA],
		stg.[CONTRACTVALUE_SA],
		stg.[CREATED],
		stg.[CUSTACCOUNT],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DEFAULTDIMENSION],
		stg.[DEFAULTFUNDINGSOURCE],
		stg.[DELIVERYLOCATION],
		stg.[DESCRIPTION],
		stg.[DLVNAME],
		stg.[EMAIL],
		stg.[ENDDATE],
		stg.[EXTENSIONDATE],
		--stg.--[FileName],
		stg.[FORMAT],
		stg.[HEADER],
		stg.[JOBID],
		stg.[JOBPAYTYPE],
		stg.[LastProcessedChange_DateTime],
		--stg.--[LSN],
		stg.[MINTIMEINCREMENT],
		stg.[MODIFIEDDATETIME],
		stg.[NAME],
		stg.[OCIP],
		stg.[OCIPGL],
		stg.[PARENTID],
		stg.[PARTITION],
		stg.[PROJBUDGETARYCONTROLON],
		stg.[PROJBUDGETINTERVAL],
		stg.[PROJBUDGETMANAGEMENT],
		stg.[PROJBUDGETOVERRUNOPTION],
		stg.[PROJCARRYFORWARDNEGATIVEBUDGET],
		stg.[PROJCARRYFORWARDREMAININGBUDGET],
		stg.[PROJDATASOURCE],
		stg.[PROJECTEDENDDATE],
		stg.[PROJECTEDSTARTDATE],
		stg.[PROJGROUPID],
		stg.[PROJID],
		stg.[PROJINVOICEPROJID],
		stg.[PROJLEDGERPOSTING],
		stg.[PROJLINEPROPERTYSEARCH],
		stg.[PROJPRICEGROUP],
		stg.[PSADOINVOICECOST],
		stg.[PSAFORECASTMODELID],
		stg.[PSAFORECASTMODELIDEXTERNAL],
		stg.[PSAINVOICEMETHOD],
		stg.[PSAPROJSTATUS],
		stg.[PSARESSCHEDSTATUS],
		stg.[PSASCHEDCALENDARID],
		stg.[PSASCHEDDURATION],
		stg.[PSASCHEDEFFORT],
		stg.[PSASCHEDENDDATE],
		stg.[PSASCHEDFROMTIME],
		stg.[PSASCHEDIGNORECALENDAR],
		stg.[PSASCHEDMILESTONE],
		stg.[PSASCHEDSCHEDULED],
		stg.[PSASCHEDSTARTDATE],
		stg.[PSASCHEDTOTIME],
		stg.[PSASCHEDUSEDURATION],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REQUIREACTIVITYEXPENSEFORECAST],
		stg.[REQUIREACTIVITYEXPENSETRX],
		stg.[REQUIREACTIVITYHOURFORECAST],
		stg.[REQUIREACTIVITYHOURTRX],
		stg.[REQUIREACTIVITYITEMFORECAST],
		stg.[REQUIREACTIVITYITEMTRX],
		stg.[SORTINGID],
		stg.[SORTINGID2_],
		stg.[SORTINGID3_],
		stg.[STARTDATE],
		stg.[STATUS],
		stg.[SUBJECT_SA],
		--stg.--[SysRowId],
		stg.[TAXGROUPID],
		stg.[TEMPLATE],
		stg.[TEMPLATEAPPLIED],
		stg.[TIMEPOSTDETAILSUMMARY],
		stg.[TYPE],
		stg.[USEALTERNATEPROJECT],
		stg.[USEBUDGETING],
		stg.[VALIDATEPROJCATEGORY],
		stg.[WIPPROJECT],
		stg.[WORKERPSAARCHITECT],
		stg.[WORKERRESPONSIBLE],
		stg.[WORKERRESPONSIBLEFINANCIAL],
		stg.[WORKERRESPONSIBLESALES]	
	FROM [staging_fo].[PROJTABLE] stg
		LEFT JOIN [synapse_fo].[PROJTABLE] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[ProjId] = tgt.[ProjId] 
		
	WHERE tgt.[RECID] IS NULL
END
